SELECT jsonb_build_object('temporary_memberships',(SELECT count(*) FROM pg_auth_members WHERE member='wa_schema_owner'::regrole AND roleid IN ('wa_private_helper_owner'::regrole,'wa_customer_verifier'::regrole,'wa_track_verifier'::regrole)),'exact_temporary_options',NOT EXISTS(SELECT 1 FROM pg_auth_members WHERE member='wa_schema_owner'::regrole AND roleid IN ('wa_private_helper_owner'::regrole,'wa_customer_verifier'::regrole,'wa_track_verifier'::regrole) AND (grantor<>'postgres'::regrole OR admin_option OR inherit_option OR NOT set_option)),'leaf_create',EXISTS(SELECT 1 FROM (VALUES('wa_private_helper_owner'),('wa_customer_verifier'),('wa_track_verifier')) x(name) WHERE has_schema_privilege(x.name,'platform_private','CREATE')),'permanent_migrator_edge',(SELECT count(*)=1 AND bool_and(roleid='wa_schema_owner'::regrole AND grantor='postgres'::regrole AND NOT admin_option AND NOT inherit_option AND set_option) FROM pg_auth_members WHERE member='wa_migrator'::regrole));
